312:     IEnumerable<Instruction> BuildVariableAssignmentInstructions(PropertyDefinition property, VariableDefinition variable)
313:     {
314:         var getMethod = property.GetMethod.GetGeneric();
315: 
316:         yield return Instruction.Create(OpCodes.Ldarg_0);
317:         yield return CreateCall(getMethod);
318: 
319:         var returnType = property.GetMethod.ReturnType;
320:         if (returnType.FullName != variable.VariableType.FullName)
321:         {
322:             yield return Instruction.Create(OpCodes.Box, returnType);
323:         }
324:         yield return Instruction.Create(OpCodes.Stloc, variable);
325:     }
