327:     int AddBeforeVariableAssignment(int index, PropertyDefinition property, VariableDefinition variable)
328:     {
329:         var i = BuildVariableAssignmentInstructions(property, variable).ToArray();
330:         instructions.Prepend(i);
331:         return index + i.Length;
332:     }
